package dev.sarp.gharchive;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.zip.GZIPInputStream;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import dev.sarp.gharchive.model.GithubEvent;
import dev.sarp.gharchive.parser.EventParser;
import dev.sarp.gharchive.writer.DataWriter;
import dev.sarp.gharchive.writer.impl.ClickHouseWriter;

public class App {
    public String getGreeting() {
        return "Hello World!";
    }

    // Pre work, testing the file opening and parsing
    public static void pre_fileWorker() {
        Path path = Path.of(
                "src/main/resources/githubData/2024-01-15-12.json.gz");

        try (
                var file = Files.newInputStream(path);
                var gzip = new GZIPInputStream(file);
                var text = new InputStreamReader(gzip, StandardCharsets.UTF_8);
                var reader = new BufferedReader(text)) {
            String line;

            EventParser parser = new EventParser(new ObjectMapper());
            long watchEventCount = 0;
            long pushEventCount = 0;
            long forkEventCount = 0;
            long allEventsCount = 0;
            long otherEventCount = 0;
            long validEventCount = 0;
            long invalidEventCount = 0;

            int batchCount = 0;
            var batch = new ArrayList<GithubEvent>();
            DataWriter writer = new ClickHouseWriter();

            while ((line = reader.readLine()) != null) {
                allEventsCount++;

                GithubEvent githubEvent;
                try {
                    githubEvent = parser.parse(line);

                } catch (JsonProcessingException
                        | IllegalArgumentException
                        | java.time.format.DateTimeParseException e) {
                    invalidEventCount++;
                    continue;
                }
                 validEventCount++;

                    batch.add(githubEvent);
                    if (batch.size() == 5000) {
                        writer.writeBatch(batch);
                        batchCount++;
                        batch.clear();
                    }
                    switch (githubEvent.type()) {
                        case "WatchEvent" -> {
                            watchEventCount++;
                        }
                        case "PushEvent" -> {
                            pushEventCount++;
                        }
                        case "ForkEvent" -> {
                            forkEventCount++;
                        }
                        default -> {
                            otherEventCount++;
                        }
                    }
                    if (allEventsCount <= 5) {

                        System.out.println(githubEvent);
                    }

            }

            if (!batch.isEmpty()) {
                writer.writeBatch(batch); 
                batchCount++;
                batch.clear();
            }
            System.out.println("BatchCount : " + batchCount);
            System.out.println("push event count : " + pushEventCount +
                    " | watch event count : " + watchEventCount +
                    " | fork event count: " + forkEventCount +
                    " | other event count : " + otherEventCount +
                    " | all event count : " + allEventsCount +
                    " | valid: " + validEventCount +
                    " | invalid: " + invalidEventCount);

        } catch (Exception e) {
            // TODO: handle exception
            System.out.println("Shit happend");
        }

    }

    public static void main(String[] args) {
        System.out.println(new App().getGreeting());
        pre_fileWorker();
    }
}
